-- NEEDS APPROVAL — not applied. Explore's own database login (design/core-modules/spec/routes.md §7):
-- `explore_reader`, its binding table, Management → Explore's settings and the questions-run log.
-- On approval this folder moves to prisma/migrations, the models in schema.prisma beside it go into
-- prisma/schema.prisma, and `pnpm db:generate` runs. The role that applies it needs CREATEROLE.
-- Saved questions need no table: a question is a custom report with one table block (lib/explore/questions.ts).
-- The grants below are `pnpm explore:reader-sql` and `pnpm explore:reader-sql --vane-new`.

-- CreateEnum
CREATE TYPE "ExploreRunResult" AS ENUM ('OK', 'REFUSED', 'TIMEOUT', 'FAILED');

-- CreateTable
CREATE TABLE "ExploreReaderScope" (
    "pid" INTEGER NOT NULL,
    "companyId" TEXT NOT NULL,
    "userId" TEXT NOT NULL,
    "tables" TEXT[] DEFAULT ARRAY[]::TEXT[],
    "boundAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "ExploreReaderScope_pkey" PRIMARY KEY ("pid")
);

-- CreateTable
CREATE TABLE "ExploreSettings" (
    "companyId" TEXT NOT NULL,
    "roles" TEXT[] DEFAULT ARRAY['SUPERADMIN', 'MANAGER']::TEXT[],
    "productScopes" JSONB NOT NULL DEFAULT '{}',
    "rowLimit" INTEGER NOT NULL DEFAULT 5000,
    "timeLimitSeconds" INTEGER NOT NULL DEFAULT 10,
    "maskPersonal" BOOLEAN NOT NULL DEFAULT true,
    "updatedById" TEXT,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "ExploreSettings_pkey" PRIMARY KEY ("companyId")
);

-- CreateTable
CREATE TABLE "ExploreQuestionRun" (
    "id" TEXT NOT NULL,
    "companyId" TEXT NOT NULL,
    "userId" TEXT,
    "title" TEXT,
    "sql" TEXT NOT NULL,
    "readFrom" TEXT[] DEFAULT ARRAY[]::TEXT[],
    "rows" INTEGER,
    "ms" INTEGER,
    "result" "ExploreRunResult" NOT NULL,
    "reason" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "ExploreQuestionRun_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "ExploreReaderScope_companyId_idx" ON "ExploreReaderScope"("companyId");
CREATE INDEX "ExploreSettings_updatedById_idx" ON "ExploreSettings"("updatedById");
CREATE INDEX "ExploreQuestionRun_companyId_createdAt_idx" ON "ExploreQuestionRun"("companyId", "createdAt");
CREATE INDEX "ExploreQuestionRun_userId_idx" ON "ExploreQuestionRun"("userId");

-- AddForeignKey
ALTER TABLE "ExploreReaderScope" ADD CONSTRAINT "ExploreReaderScope_companyId_fkey" FOREIGN KEY ("companyId") REFERENCES "Company"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ExploreSettings" ADD CONSTRAINT "ExploreSettings_companyId_fkey" FOREIGN KEY ("companyId") REFERENCES "Company"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ExploreSettings" ADD CONSTRAINT "ExploreSettings_updatedById_fkey" FOREIGN KEY ("updatedById") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "ExploreQuestionRun" ADD CONSTRAINT "ExploreQuestionRun_companyId_fkey" FOREIGN KEY ("companyId") REFERENCES "Company"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ExploreQuestionRun" ADD CONSTRAINT "ExploreQuestionRun_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- Vane's reader reads the settings and the log (pnpm explore:reader-sql --vane-new); it never reads the binding.
-- Every readable table: rows of the bound workspace only, for the readers; nothing changes for anyone else.
ALTER TABLE "ExploreSettings" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "app_all" ON "ExploreSettings" AS PERMISSIVE FOR ALL TO PUBLIC USING (true) WITH CHECK (true);
CREATE POLICY "vane_workspace" ON "ExploreSettings" AS RESTRICTIVE FOR SELECT TO vane_reader USING ("companyId" = (SELECT s."companyId" FROM "VaneReaderScope" s WHERE s."pid" = pg_backend_pid()));
GRANT SELECT ("companyId", "roles", "productScopes", "rowLimit", "timeLimitSeconds", "maskPersonal", "updatedById", "updatedAt") ON "ExploreSettings" TO vane_reader;
ALTER TABLE "ExploreQuestionRun" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "app_all" ON "ExploreQuestionRun" AS PERMISSIVE FOR ALL TO PUBLIC USING (true) WITH CHECK (true);
CREATE POLICY "vane_workspace" ON "ExploreQuestionRun" AS RESTRICTIVE FOR SELECT TO vane_reader USING ("companyId" = (SELECT s."companyId" FROM "VaneReaderScope" s WHERE s."pid" = pg_backend_pid()));
GRANT SELECT ("id", "companyId", "userId", "title", "sql", "readFrom", "rows", "ms", "result", "reason", "createdAt") ON "ExploreQuestionRun" TO vane_reader;


-- explore_reader (pnpm explore:reader-sql)
-- The login. NOLOGIN here: give it a password by hand on the server (docs/vane.md, "Setting it up"); none is kept in git.
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'explore_reader') THEN CREATE ROLE explore_reader NOLOGIN; END IF;
END $$;
GRANT USAGE ON SCHEMA public TO explore_reader;

-- The binding: the app writes (pid → workspace, person, tables) inside the reading transaction. The reader sees only its own row and cannot write it.
ALTER TABLE "ExploreReaderScope" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "app_all" ON "ExploreReaderScope" AS PERMISSIVE FOR ALL TO PUBLIC USING (true) WITH CHECK (true);
CREATE POLICY "explore_own_pid" ON "ExploreReaderScope" AS RESTRICTIVE FOR SELECT TO explore_reader USING ("pid" = pg_backend_pid());
GRANT SELECT ("pid", "companyId", "tables") ON "ExploreReaderScope" TO explore_reader;

-- Every table it reads: the bound workspace's rows of the bound tables only. Row security and app_all are already on (20261012120000_vane).
